records_anchor = '''    private suspend fun records(projectId: String, entityType: String? = null): List<LocalRecord> {\n'''
raw_helper = '''    private suspend fun rawRecords(projectId: String): List<LocalRecord> =\n        loadSnapshot(projectId)\n            .asSequence()\n            .filter { it.operation == "upsert" }\n            .mapNotNull { entity ->\n                val payload = entity.payloadJson?.let { raw ->\n                    runCatching { json.parseToJsonElement(raw) as? JsonObject }.getOrNull()\n                } ?: return@mapNotNull null\n                LocalRecord(entity, payload)\n            }\n            .toList()\n\n'''
if records_anchor not in text:
    raise RuntimeError("records anchor missing")
text = text.replace(records_anchor, raw_helper + records_anchor, 1)

helper_anchor = '''    private fun JsonObject.withDefaults(defaults: Map<String, JsonElement>): JsonObject = buildJsonObject {\n'''
helper = '''    private fun jsonStringMap(values: Map<String, String>): JsonObject = buildJsonObject {\n        values.forEach { (key, value) -> put(key, value) }\n    }\n\n'''
if helper_anchor not in text:
    raise RuntimeError("JSON helper anchor missing")
text = text.replace(helper_anchor, helper + helper_anchor, 1)

path.write_text(text, encoding="utf-8")
